// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 delay, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        delay = bound(delay, 1, 1000 days);
        amount = bound(amount, 0, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + delay);
        // Acc(actor) returns (unlockTime, balance); reference stores the exact future timestamp
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime == block.timestamp + delay);
    }
}
